class Solution { public:long long maxOutput(int n,vector<vector<int>>& edges,vector<int>& price){vector<vector<int>> graph(n);for(auto& edge:edges){graph[edge[0]].push_back(edge[1]);graph[edge[1]].push_back(edge[0]);}vector<int> parent(n,-2),order(n);parent[0]=-1;int size=1;for(int index=0;index<size;++index){int node=order[index];for(int next:graph[node])if(parent[next]==-2){parent[next]=node;order[size++]=next;}}vector<long long> full(n),excluded(n);long long answer=0;for(int index=n-1;index>=0;--index){int node=order[index];long long bestFull=price[node],bestExcluded=0;for(int child:graph[node])if(parent[child]==node){answer=max({answer,bestFull+excluded[child],bestExcluded+full[child]});bestFull=max(bestFull,price[node]+full[child]);bestExcluded=max(bestExcluded,price[node]+excluded[child]);}full[node]=bestFull;excluded[node]=bestExcluded;}return answer;} };
